using Types=CheckpointTypes;using FF=CheckpointFF;using State=sofa::core::behavior::MechanicalState<Types>;
struct Matrix:sofa::core::behavior::StiffnessMatrixAccumulator{std::map<std::pair<unsigned,unsigned>,double>entries;void add(sofa::SignedIndex r,sofa::SignedIndex c,double v)override{if(v)entries[{unsigned(r),unsigned(c)}]+=v;}void add(sofa::SignedIndex r,sofa::SignedIndex c,float v)override{add(r,c,double(v));}};
Matrix jacobian(State*s,const std::vector<FF*>&fields){Matrix result;sofa::core::behavior::StiffnessMatrix matrix;matrix.setMatrixAccumulator(&result,s);for(auto*f:fields)f->buildStiffnessMatrix(&matrix);return result;}
void dumpSystem(sofa::simulation::Node*root,const std::string&path){
 auto*solver=root->get<sofa::core::behavior::LinearSolver>(sofa::core::objectmodel::BaseContext::SearchDown);if(!solver||!solver->getLinearSystem())throw std::runtime_error("public linear system unavailable");auto*system=solver->getLinearSystem();auto*A=system->getSystemBaseMatrix();auto*b=system->getSystemRHSBaseVector();auto*x=system->getSystemSolutionBaseVector();if(!A||!b||!x||A->rowSize()!=A->colSize()||b->size()!=A->rowSize()||x->size()!=b->size())throw std::runtime_error("linear system diagnostic sizes");
 std::ofstream out(path);out<<std::setprecision(17)<<A->rowSize()<<'\n';for(int r=0;r<A->rowSize();++r){out<<"V "<<r<<' '<<b->element(r)<<' '<<x->element(r)<<'\n';for(int c=0;c<A->colSize();++c){double a=A->element(r,c);if(a)out<<"A "<<r<<' '<<c<<' '<<a<<'\n';}}if(!out)throw std::runtime_error("linear system diagnostic write");
}
void writeCoord(std::ostream&out,const Types::Coord&p){for(int j=0;j<3;++j)out<<p.getCenter()[j]<<' ';for(int j=0;j<4;++j)out<<p.getOrientation()[j]<<' ';out<<'\n';}
Types::Coord readCoord(std::istream&in){Types::Coord p;for(int j=0;j<3;++j)p.getCenter()[j]=scalar(in);double norm=0;for(int j=0;j<4;++j){double v=scalar(in);p.getOrientation()[j]=v;norm+=v*v;}need(std::abs(norm-1)<1e-8,"checkpoint unit quaternion");return p;}
bool sameCoord(const Types::Coord&a,const Types::Coord&b){for(int j=0;j<7;++j)if(a[j]!=b[j])return false;return true;}
Types::VecDeriv forces(State*state,const std::vector<FF*>&fields){FF::DataVecDeriv result;result.setValue(Types::VecDeriv(state->getSize()));sofa::core::MechanicalParams mp;for(auto*f:fields)f->addForce(&mp,result,*state->read(sofa::core::vec_id::read_access::position),*state->read(sofa::core::vec_id::read_access::velocity));return result.getValue();}
void fieldState(FF*f,std::ostream*out,std::istream*in){auto name=f->getClassName();if(name=="CurvedMaterialContact"){if(out)writeCurveState(f,*out);else readCurveState(f,*in);}else if(name=="FrameLayerNetwork"){if(out)writeFrameState(f,*out);else readFrameState(f,*in);}else if(name=="RoutedCable"){if(out)writeCableState(f,*out);else readCableState(f,*in);}else need(name=="ConservativeBeam"||name=="SpatialLoad"||dynamic_cast<sofa::core::behavior::Mass<Types>*>(f),"unhandled physical-memory field");}
int main(int argc,char**argv){try{
 need(argc==10,"SDK SCENE LOCAL_STEPS INPUT_OR_- OUTPUT FRAME BEAM CONTACT SUMMARY");unsigned localSteps=std::stoul(argv[3]);need(localSteps>=20&&localSteps<=48000&&localSteps%20==0,"bounded multiple-of20 checkpoint chunk");std::ifstream oldOutput(argv[5]);need(!oldOutput,"refuse old checkpoint");
 sofa::simulation::graph::init();sofa::simpleapi::init();sofa::helper::system::PluginRepository.addFirstPath(std::string(argv[1])+"/lib");sofa::simulation::Simulation::theSimulation=sofa::simpleapi::createSimulation("DAG");for(int i=6;i<9;++i)need(sofa::simpleapi::importPlugin(argv[i]),"checkpoint plugin load");auto root=sofa::simulation::node::load(argv[2]);need(bool(root),"checkpoint scene load");sofa::simulation::node::initRoot(root.get());auto*body=root->getChild("Multilayer");need(body,"checkpoint body");auto*state=dynamic_cast<State*>(body->getMechanicalState());need(state,"checkpoint rigid state");auto*ctx=static_cast<sofa::core::objectmodel::BaseContext*>(body);std::vector<FF*>fields;FF*contact=nullptr;for(auto*f:ctx->getObjects<FF>(sofa::core::objectmodel::BaseContext::Local)){fields.push_back(f);if(f->getClassName()=="CurvedMaterialContact")contact=f;}need(contact,"checkpoint contact");unsigned globalStep=0;double startTime=root->getTime(),restoredForceError=0,restoredJacobianError=0;
 if(std::string(argv[4])!="-"){
  std::ifstream in(argv[4]);std::string magic;need(bool(in>>magic)&&magic=="REGRIP_PHYSICAL_CHECKPOINT_1","checkpoint version");double h=scalar(in),time=scalar(in);need(h==root->getDt(),"checkpoint timestep changed");need(bool(in>>globalStep)&&globalStep>0&&globalStep%20==0&&globalStep<=240000,"checkpoint global step");size_t n;need(bool(in>>n)&&n==state->getSize(),"checkpoint node count");const auto&rest=state->read(sofa::core::vec_id::read_access::restPosition)->getValue();for(size_t i=0;i<n;++i)need(sameCoord(readCoord(in),rest[i]),"checkpoint material reference changed");auto x=rest;for(auto&p:x)p=readCoord(in);Types::VecDeriv v(n),expected(n);for(auto&d:v)for(int j=0;j<6;++j)d[j]=scalar(in);state->write(sofa::core::vec_id::write_access::position)->setValue(x);state->write(sofa::core::vec_id::write_access::velocity)->setValue(v);
  size_t count;need(bool(in>>count)&&count==fields.size(),"checkpoint field count");for(auto*f:fields){std::string type,name;need(bool(in>>std::quoted(type)>>std::quoted(name))&&type==f->getClassName()&&name==f->getName(),"checkpoint field identity/order");fieldState(f,nullptr,&in);}for(auto&d:expected)for(int j=0;j<6;++j)d[j]=scalar(in);in>>std::ws;need(in.eof(),"trailing/corrupt checkpoint data");root->setTime(time);root->execute<sofa::simulation::UpdateSimulationContextVisitor>(sofa::core::execparams::defaultInstance());need(curveCheckpointSteps(contact)==globalStep,"contact checkpoint counter differs");auto actual=forces(state,fields);for(unsigned i=0;i<n;++i)for(int j=0;j<6;++j)restoredForceError=std::max(restoredForceError,std::abs(actual[i][j]-expected[i][j]));need(restoredForceError<1e-12,"checkpoint restored force differs");startTime=time;
  std::ifstream jin(std::string(argv[4])+".J");size_t entries;need(bool(jin>>entries)&&entries<10000000,"checkpoint Jacobian sidecar");auto J=jacobian(state,fields);std::map<std::pair<unsigned,unsigned>,double>expectedJ;for(size_t k=0;k<entries;++k){unsigned r,c;need(bool(jin>>r>>c)&&r<6*n&&c<6*n,"checkpoint Jacobian index");expectedJ[{r,c}]=scalar(jin);}for(auto&v:expectedJ)restoredJacobianError=std::max(restoredJacobianError,std::abs(v.second-J.entries[v.first]));for(auto&v:J.entries)restoredJacobianError=std::max(restoredJacobianError,std::abs(v.second-expectedJ[v.first]));std::cout<<std::setprecision(17)<<"RESTORED_JACOBIAN_ERROR "<<restoredJacobianError<<'\n';need(restoredJacobianError<1e-13,"checkpoint restored tangent differs");
 }
 need(globalStep+localSteps<=240000,"checkpoint total step cap");for(unsigned i=0;i<localSteps;++i){sofa::simulation::node::animate(root.get());if(globalStep+i+1==8001)dumpSystem(root.get(),std::string(argv[5])+".MBKS");}globalStep+=localSteps;need(curveCheckpointSteps(contact)==globalStep,"actual contact step count differs");
 std::ofstream out(argv[5]);need(bool(out),"checkpoint output");out<<std::setprecision(17)<<"REGRIP_PHYSICAL_CHECKPOINT_1\n"<<root->getDt()<<' '<<root->getTime()<<' '<<globalStep<<'\n'<<state->getSize()<<'\n';for(const auto&p:state->read(sofa::core::vec_id::read_access::restPosition)->getValue())writeCoord(out,p);for(const auto&p:state->read(sofa::core::vec_id::read_access::position)->getValue())writeCoord(out,p);for(const auto&d:state->read(sofa::core::vec_id::read_access::velocity)->getValue()){for(int j=0;j<6;++j)out<<d[j]<<' ';out<<'\n';}out<<fields.size()<<'\n';for(auto*f:fields){out<<std::quoted(f->getClassName())<<' '<<std::quoted(f->getName())<<'\n';fieldState(f,&out,nullptr);}for(const auto&d:forces(state,fields)){for(int j=0;j<6;++j)out<<d[j]<<' ';out<<'\n';}out.close();need(bool(out),"checkpoint write failure");
 auto J=jacobian(state,fields);std::ofstream jout(std::string(argv[5])+".J");jout<<std::setprecision(17)<<J.entries.size()<<'\n';for(auto&v:J.entries)jout<<v.first.first<<' '<<v.first.second<<' '<<v.second<<'\n';jout.close();need(bool(jout),"Jacobian sidecar write");
 std::ofstream summary(argv[9]);summary<<std::setprecision(17)<<"{\"local_steps\":"<<localSteps<<",\"global_steps\":"<<globalStep<<",\"start_time\":"<<startTime<<",\"end_time\":"<<root->getTime()<<",\"restored_force_error\":"<<restoredForceError<<",\"restored_jacobian_error\":"<<restoredJacobianError<<"}\n";summary.close();need(bool(summary),"checkpoint summary write");std::cout<<"CHECKPOINT actual local_steps="<<localSteps<<" global_steps="<<globalStep<<" time="<<root->getTime()<<'\n';sofa::simulation::node::unload(root);root.reset();sofa::simulation::Simulation::theSimulation.reset();sofa::simpleapi::cleanup();sofa::simulation::graph::cleanup();return 0;
}catch(const std::exception&e){std::cerr<<"[ERROR] "<<e.what()<<'\n';return 1;}}
